(()=>{'use strict';
const D=window.SCHOOL_DATA,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),levels=D.LEVELS,codes=Object.keys(D.COURSES);
const S={client:null,user:null,mine:null,view:null,route:'home',course:'F101',lesson:0,adminTab:'inbox',selected:null,students:null,page:0,search:'',busy:false,dirty:false,epoch:0,ready:false,online:navigator.onLine,setup:false,error:'',lastCheck:null,offset:0,cert:null,editNotice:null};
const date=v=>v?new Date(v).toLocaleString('en-GB',{timeZone:'Africa/Lusaka',dateStyle:'medium',timeStyle:'short'}):'—';
const lev=id=>levels.find(x=>x.id===id),levelFor=code=>levels.find(l=>l.courses.includes(code)),spec=code=>D.ESSAY_SPECS[levelFor(code).id],staff=()=>!!S.mine?.staff,owner=()=>S.mine?.staff?.role==='owner',active=()=>!!S.mine?.profile?.active,arr=(k,r=S.mine)=>r?.[k]||[],assignment=(code,r=S.mine)=>arr('assignments',r).find(a=>a.course===code),learning=(code,i,r=S.mine)=>arr('learning',r).find(a=>a.course===code&&a.lesson===i),wordCount=s=>String(s||'').trim().split(/\s+/).filter(Boolean).length;
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${({book:'<path d="M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3zM12 6v16"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6"/>',file:'<path d="M5 3h9l5 5v13H5zM14 3v6h5M8 13h8M8 17h6"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M17 15a5 5 0 0 1 4 5"/>',check:'<path d="m4 12 5 5L20 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>'})[name]||'<circle cx="12" cy="12" r="8"/>'}</svg>`;
const btn=(label,action,cls='secondary',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const chip=(text,kind='')=>`<span class="chip ${kind}">${esc(text)}</span>`;
const heading=(eyebrow,title,text='')=>`<div class="kicker">${eyebrow}</div><h1 tabindex="-1">${title}</h1>${text?`<p class="lead">${text}</p>`:''}`;
const notice=(text,kind='')=>`<div class="notice ${kind}">${text}</div>`;
const input=(label,name,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const selectLevels=(name,value='',list=levels)=>`<select name="${name}">${list.map(l=>`<option value="${esc(l.id)}" ${l.id===value?'selected':''}>${esc(l.name)}</option>`).join('')}</select>`;
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,7000)}
function clearPrivate(){S.mine=null;S.view=null;S.adminLoading=false;S.adminRequest=(S.adminRequest||0)+1;S.selected=null;S.students=null;S.adminNotices=[];S.cert=null;S.certAdmin=false;S.dirty=false;S.epoch++;if($('modal').open)$('modal').close();$('modal').replaceChildren();$('main').replaceChildren()}
function status(){const el=$('status');el.className='statusbar'+(S.error?' error':'');el.innerHTML=`${S.error?esc(S.error):!S.ready?'Connecting to your school…':S.user?`Signed in · ${S.online?'Cloud records checked '+date(S.lastCheck):'Offline — changes cannot be saved'}`:'Public curriculum · Sign in for your personal records'} ${S.dirty?' · Unsaved changes':''}<button id="statusRefresh" type="button">Refresh</button>`;$('statusRefresh').onclick=()=>refresh(true)}
function chrome(){const identity=S.user?`${esc(S.mine?.profile?.profile?.name||S.user.email)}<br>${staff()?'School '+esc(S.mine.staff.role):S.mine?.profile?(active()?'Registered student':'Access suspended'):'Complete school registration'}`:'';$('account').innerHTML=S.user?`<span class="identity">${identity}</span>${btn('Sign out','signout','gold')}`:btn('Student / staff sign in','signin','gold');let tabs=[['home','Home'],['register','Registration'],['dashboard','My studies'],['curriculum','Curriculum'],['lessons','Lessons'],['assignments','Assignments'],['exams','Examinations'],['fees','Fees & certificates'],['files','My files'],['records','My record'],['messages','Registrar'],['library','Library'],['handbook','Handbook'],['calendar','Calendar']];if(staff())tabs.push(['admin','School administration']);$('tabs').innerHTML=tabs.map(([r,t])=>`<button type="button" data-route="${r}" class="${S.route===r?'active ':''}${r==='admin'?'admin':''}" ${S.route===r?'aria-current="page"':''}>${t}</button>`).join('');status()}
async function call(name,args={}){if(!S.client||!S.user)throw Error('Sign in first.');if(!navigator.onLine)throw Error('You are offline. Keep this tab open, reconnect, then save.');const {data,error}=await S.client.rpc('school_'+name,Object.fromEntries(Object.entries(args).map(([k,v])=>['p_'+k,v])));if(error)throw error;return Array.isArray(data)&&['save_learning','assignment','exam','file'].includes(name)?data[0]:data}
async function refresh(force=false){if(S.refreshing)return;if(force&&S.dirty&&!confirm('Refresh will discard unsaved text on this page. Copy it first if needed. Continue?'))return;if(force)S.dirty=false;S.refreshing=true;let epoch=S.epoch;try{const {data,error}=await S.client.auth.getSession();if(error)throw error;const user=data.session?.user||null;if(user?.id!==S.user?.id){clearPrivate();S.user=user;epoch=S.epoch;S.route='home';}if(!user){S.ready=true;S.online=navigator.onLine;S.error='';chrome();render();return}const result=await call('snapshot',{student:null});if(epoch!==S.epoch)return;const oldRole=S.mine?.staff?.role,oldActive=S.mine?.profile?.active;S.mine=result;if(S.cert&&!S.certAdmin)S.cert=arr('certificates',result).find(c=>c.id===S.cert.id)||null;S.offset=new Date(result.server_time).getTime()-Date.now();if((oldRole&&!result.staff)||(oldActive&&!result.profile?.active)){S.view=null;S.students=null;S.adminNotices=[];S.selected=null;S.cert=null;S.certAdmin=false;S.dirty=false;S.epoch++;S.route=result.profile?.active?'dashboard':'home';if($('modal').open)$('modal').close();$('modal').replaceChildren();}S.setup=false;S.online=true;S.error='';S.lastCheck=new Date().toISOString();S.ready=true;chrome();if((S.route==='admin'||S.certAdmin)&&staff()){if(S.selected){const e=S.epoch,selected=S.selected;const v=await call('snapshot',{student:selected});if(e!==S.epoch||selected!==S.selected||!staff())return;S.view=v;if(S.cert&&S.certAdmin)S.cert=arr('certificates',v).find(c=>c.id===S.cert.id)||null;}else if(S.adminTab==='students')S.students=await call('admin_students',{search:S.search,page:S.page});}if(!S.dirty&&!S.busy)render();}catch(e){S.ready=true;S.online=false;S.setup=/PGRST202|schema cache|does not exist/.test(e.code+' '+e.message);S.error=S.setup?'Bible-school database setup is still required.':e.message||'Connection unavailable. Saved records may be out of date.';chrome();if(!S.mine||force)render();}finally{S.refreshing=false}}
async function work(fn,success='Saved to the school database.'){if(S.busy)return;const epoch=S.epoch;S.busy=true;document.querySelectorAll('#main button[type=submit]').forEach(b=>b.disabled=true);try{await fn();if(epoch!==S.epoch)return;S.dirty=false;toast(success);S.busy=false;await refresh(true);}catch(e){if(epoch===S.epoch){toast(e.message||'The request failed. Your unsaved work is still here.');S.error=e.message;status();}}finally{S.busy=false;document.querySelectorAll('#main button[type=submit]').forEach(b=>b.disabled=false)}}
async function go(route){if(S.dirty&&!confirm('Leave this page without saving? Copy or save your draft first.'))return;S.dirty=false;S.route=route;S.cert=null;if(route==='admin'&&staff())await loadAdmin();else{chrome();render()}$('main').scrollIntoView({block:'start',behavior:'auto'});$('main').querySelector('h1')?.focus({preventScroll:true});history.replaceState(null,'','#'+route)}
function gate(){if(!S.ready)return '<div class="card empty">Checking your account…</div>';if(S.setup)return `<div class="card empty"><h2>Activate the shared Bible school</h2><p>The church connection works, but the separate Bible-school installer must be run by the project owner.</p><a class="btn" href="school-setup.html">School setup instructions</a><p class="small">Do not rerun the church setup script. The school has its own private installer.</p></div>`;if(!S.user)return `<div class="card empty">${icon('shield')}<h2>Your own private school record</h2><p>Sign in or create an account. After email confirmation, complete registration and begin immediately.</p>${btn('Sign in / create account','signin','')}</div>`;if(!S.mine)return `<div class="card empty"><h2>Records unavailable</h2><p>${esc(S.error||'Please reconnect and refresh.')}</p></div>`;if(S.mine.profile&&!active())return `<div class="card empty"><h2>Student access is suspended</h2><p>Please contact the school office on 0979 554 970. Your records have not been erased.</p></div>`;if(!S.mine.profile)return `<div class="card empty"><h2>Complete your school registration</h2><p>Your email sign-in is ready. Tell the school who you are and choose your study level.</p>${btn('Register as a student','route:register','')}</div>`;return ''}
function render(){chrome();let html='';const publicRoutes=['home','curriculum','library','handbook','calendar'];if(!publicRoutes.includes(S.route)&&S.route!=='register'&&S.route!=='admin'&&!(S.route==='fees'&&S.certAdmin&&staff()))html=gate();if(!html){const views={home,register,dashboard,curriculum,lessons,assignments,exams,fees,files,records,messages,library,handbook,calendar,admin};html=(views[S.route]||home)()}$('main').innerHTML=html;bind();updateClock()}
function home(){return `<div class="card dark hero"><div class="kicker" style="color:#e4c16e">Established in the Word · Sent in the Spirit</div><h1>A Bible school that trains,<br>tests and sends.</h1><p>Study faithfully. Submit your work. Receive correction. Your learning and the registrar’s decisions now meet in one private, shared school record.</p><div class="actions">${btn(active()?'Continue my studies':'Register for study','route:'+ (active()?'dashboard':'register'),'gold')}${btn('Explore the curriculum','route:curriculum','secondary')}${staff()?btn('Open school administration','route:admin','gold'):''}</div></div><div class="grid"><div class="card"><div class="value">9</div><h3>Levels of formation</h3><p class="small">From foundations to advanced theological study and supervised ministry.</p></div><div class="card"><div class="value">27</div><h3>Courses, carefully assessed</h3><p class="small">Lessons, objective papers, essays and level examinations.</p></div><div class="card"><div class="value">K150</div><h3>Certificate fee only</h3><p class="small">Registration is free. The registrar verifies payment and academic eligibility before issuing a certificate.</p></div></div>${S.user&&!S.mine?.profile&&!staff()?notice('Your account is signed in. Complete school registration to start studying.'):''}${S.mine?.profile&&!active()?notice('Your student access is suspended. Contact the registrar.','bad'):''}${S.setup?gate():''}${arr('notices').length?`<h2 style="margin-top:28px">School notices</h2>${arr('notices').map(n=>`<article class="card accent"><h3>${esc(n.title)}</h3><p class="preserve">${esc(n.body)}</p><span class="small">${date(n.updated_at)}</span></article>`).join('')}`:''}<div class="grid two" style="margin-top:20px"><div class="card"><h2>Begin with a covenant.</h2><p>Be serious in the Word before you are present on the platform. Keep honest records, submit original work and welcome correction.</p>${btn('Read the student handbook','route:handbook')}</div><div class="card"><h2>Private by design.</h2><p>Your registration, drafts, submissions, evidence and marks are accessible to you and appointed school administrators—not to other students or all church leaders.</p><p class="small">An internet connection is required to save and share work. The old offline staff code no longer grants administrative access.</p></div></div>`}
function register(){if(!S.user||!S.ready||S.setup||!S.mine)return heading('Admission','School registration')+gate();if(S.mine.profile){const p=S.mine.profile;return heading('Your registration',esc(p.profile.name))+`<div class="card"><div class="row between">${chip(p.student_no)}${chip(p.active?'Active student':'Suspended',p.active?'green':'red')}</div><p>${esc(p.email)}</p><p>Registered ${date(p.registered_at)}</p><h3>Your levels</h3><ul>${p.levels.map(l=>`<li>${esc(lev(l)?.name||l)}</li>`).join('')}</ul>${active()?`<form id="enrolForm"><label>Add another study level${selectLevels('level','',levels.filter(l=>!p.levels.includes(l.id)))}</label><button type="submit" class="btn secondary" ${p.levels.length===levels.length?'disabled':''}>Add level to my studies</button></form>`:''}<p class="small">Ask the registrar through Messages to correct your name or other enrolment details.</p>${btn('Open my studies','route:dashboard','')}${btn('Contact the registrar','route:messages')}</div>`}
return heading('Admission · no registration fee','Become a student','Email confirmation is complete. Registration is active immediately after you accept the covenant below.')+`<form id="registration" class="card"><div class="grid two">${input('Full name — as it should appear on your certificate','name','','text','required maxlength="120"')}${input('Preferred name','preferred','','text','maxlength="120"')}${input('WhatsApp / phone','phone','','tel','required maxlength="40"')}${input('Congregation or ministry','congregation','','text','required maxlength="200"')}${input('Country','country','Zambia')}${input('City / town','city','Lusaka')}${input('Date of birth — optional','dob','','date')}${input('Ministry role — optional','ministry')}${input('Highest schooling completed','education')}${input('Study hours per week','weekly_hours','4','number','min="1" max="80"')}</div><label>Ministry / salvation testimony — optional<textarea name="testimony" maxlength="4000"></textarea></label><h3 style="margin-top:25px">Choose your level(s)</h3><div class="grid two">${levels.map((l,i)=>`<label class="check"><input type="checkbox" name="levels" value="${l.id}" ${i===0?'checked':''}><span><b>${esc(l.name)}</b><br><span class="small">${esc(l.short)}</span></span></label>`).join('')}</div><label class="check"><input type="checkbox" name="covenant" required><span>I accept the study covenant: honest, original work; serious study and supervised ministry; no invented references. I understand that my saved school record and evidence are shared with appointed school administrators.</span></label><p class="small">Sign-in email: ${esc(S.user.email)}. No school-admin role is granted by registering.</p><button class="btn" type="submit">Complete registration & begin</button></form>`}
function dashboard(){const p=S.mine.profile;let courses=p.levels.flatMap(l=>lev(l).courses),done=arr('assignments').filter(a=>a.passed).length;return heading('Your place','My studies',`${esc(p.profile.name)} · ${esc(p.student_no)}`)+`<div class="grid"><div class="card"><div class="value">${arr('learning').filter(a=>a.completed).length}</div><h3>Lessons completed</h3></div><div class="card"><div class="value">${done}/${courses.length}</div><h3>Courses passed</h3></div><div class="card"><div class="value">${arr('assignments').filter(a=>a.status==='submitted').length+arr('exams').filter(a=>a.status==='submitted').length}</div><h3>Awaiting marking</h3></div></div><h2 style="margin-top:28px">Your next faithful step</h2><div class="grid two">${courses.map(c=>{let a=assignment(c),count=D.COURSES[c].lessons.length,completed=arr('learning').filter(r=>r.course===c&&r.completed).length;return `<div class="card"><div class="row between">${chip(c)}${chip(a?.passed?'Passed':a?.status||'Not submitted',a?.passed?'green':'')}</div><h3 style="margin-top:15px">${esc(D.COURSES[c].title)}</h3><div class="progress"><i style="width:${completed/count*100}%"></i></div><p class="small">${completed}/${count} lessons complete${a?.final_score!=null?' · Final '+a.final_score+'%':''}</p>${a?.feedback?`<p class="small preserve">Registrar: ${esc(a.feedback)}</p>`:''}<div class="actions">${btn('Open lessons','course:'+c)}${btn('Assignment','assignment:'+c)}</div></div>`}).join('')}</div>`}
function curriculum(){return heading('Nine levels · twenty-seven courses','The curriculum','The teaching content is preserved from your school file. Formal assessment marks and approvals are now recorded by the server.')+levels.map(l=>`<section class="card"><div class="kicker">${esc(l.id)}</div><h2>${esc(l.name)}</h2><p class="lead">${esc(l.short)}</p><div class="grid two">${l.courses.map(c=>`<div><h3>${esc(D.COURSES[c].title)}</h3><p class="small">${D.COURSES[c].lessons.length} lessons · 20 objective questions + ${esc(spec(c).kind)}</p><p>${esc(D.COURSES[c].assignment)}</p>${btn('Open lessons','course:'+c)}</div>`).join('')}</div></section>`).join('')}
function courseSidebar(route){const enrolled=S.mine.profile.levels.flatMap(l=>lev(l).courses);if(!enrolled.includes(S.course))S.course=enrolled[0];return `<aside class="card sticky"><div class="kicker">Your courses</div>${enrolled.map(c=>`<button class="course-link ${S.course===c?'active':''}" data-action="${route==='lessons'?'course':'assignment'}:${c}">${esc(D.COURSES[c].title)}</button>`).join('')}</aside>`}
function questionList(qs,answers=[],locked=false,prefix='q'){return qs.map((q,i)=>`<div class="question"><span class="num">QUESTION ${i+1}</span><strong>${esc(q[0])}</strong>${q[1].map((o,j)=>`<label class="option"><input type="radio" name="${prefix}${i}" value="${j}" ${answers[i]===j?'checked':''} ${locked?'disabled':''}><span><b>${String.fromCharCode(65+j)}.</b> ${esc(Array.isArray(o)?o[0]:o)}</span></label>`).join('')}</div>`).join('')}
function lessons(){let side=courseSidebar('lessons'),course=D.COURSES[S.course];S.lesson=Math.max(0,Math.min(S.lesson,course.lessons.length-1));const l=course.lessons[S.lesson],r=learning(S.course,S.lesson),unlocked=S.lesson===0||learning(S.course,S.lesson-1)?.completed;return heading('Classroom',esc(course.title))+`<div class="layout">${side}<div><div class="row" style="margin-bottom:15px">${course.lessons.map((x,i)=>btn('Lesson '+(i+1)+(learning(S.course,i)?.completed?' ✓':''),'lesson:'+i,i===S.lesson?'':'secondary')).join('')}</div><article class="card prose"><div class="row between">${chip('Lesson '+(S.lesson+1))}${r?.completed?chip('Completed','green'):''}</div><h2 style="margin-top:16px">${esc(l.title)}</h2><p><b>Scripture:</b> ${esc((l.scripture||[]).join(' · '))}</p><h3>Learning objectives</h3><ul>${(l.objectives||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${(l.content||[]).map(x=>`<h3>${esc(x[0])}</h3><p>${esc(x[1])}</p>`).join('')}${l.example?`<blockquote><b>Consider this</b><p>${esc(l.example)}</p></blockquote>`:''}<h3>Put the lesson into practice</h3><p>${esc(l.activity||'Reflect prayerfully on the lesson.')}</p></article>${!unlocked?notice('Complete the preceding lesson before recording progress here.'):`<form id="learningForm" class="card" data-version="${r?.version||0}"><h2>Reflection & lesson check</h2><label>Your private study notes<textarea name="notes" maxlength="20000">${esc(r?.notes||'')}</textarea></label>${questionList(l.quiz,r?.answers||[])}${r?.score!=null?notice('Last lesson check: '+r.score+'%. A score of 50% or above completes this lesson.',r.completed?'good':''):''}<p class="small">This is a formative check. You may study and try it again.</p><div class="actions"><button class="btn secondary" type="submit" value="save">Save notes & answers</button><button class="btn" type="submit" value="finish">Check & complete lesson</button></div></form>`}</div></div>`}
function assignments(){const side=courseSidebar('assignments'),c=S.course,sp=spec(c),r=assignment(c),qs=D.BANK[c],locked=['submitted','graded'].includes(r?.status),ready=D.COURSES[c].lessons.every((_,i)=>learning(c,i)?.completed);return heading('Assessment','Assignment centre','Save a draft to move between devices. Checking Part A seals your objective answers; only the registrar may return a paper.')+`<div class="layout">${side}<div><div class="card"><div class="row between">${chip(c)}${chip(r?.status||'Not submitted',r?.passed?'green':'')}</div><h2 style="margin-top:16px">${esc(D.COURSES[c].title)}</h2><p>${esc(D.COURSES[c].assignment)}</p><p class="small">${sp.minWords.toLocaleString()}–${sp.maxWords.toLocaleString()} essay words · ${sp.sources}+ sources · Pass ${sp.passMark}%</p><details><summary>Required elements & marking rubric</summary><ol>${sp.requires.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${sp.rubric.map(r=>`<p><b>${esc(r[0])} · ${r[1]} marks</b><br><span class="small">${esc(r[2])}</span></p>`).join('')}</details>${r?.feedback?notice(`<b>Registrar feedback</b><p class="preserve">${esc(r.feedback)}</p>`):''}${r?.mcq!=null?`<p><b>Part A: ${r.mcq}%</b> · Sealed${r.final_score!=null?' · Essay '+r.essay_score+'% · Final '+r.final_score+'%':''}</p>`:''}</div>${!ready&&!locked?notice('Complete all lessons in this course before submitting an assignment.'):`<form id="assignmentForm" class="card" data-version="${r?.version||0}"><h2>Part A · Exact-answer selection</h2>${questionList(qs,r?.answers||[],locked||r?.mcq!=null)}<div class="divider"></div><h2>Part B · ${esc(sp.kind)}</h2><p>${esc(sp.blurb)}</p><label>Your essay<textarea name="essay" maxlength="250000" style="min-height:320px" ${locked?'readonly':''}>${esc(r?.essay||'')}</textarea></label><p class="small" id="wordCount">${wordCount(r?.essay)} words</p><label>Bibliography / references<textarea name="bibliography" maxlength="40000" ${locked?'readonly':''}>${esc(r?.bibliography||'')}</textarea></label><p class="small">Upload PDFs/images under My files <b>before</b> handing in. Files supplement—not replace—the typed essay. Keep quotes and references verifiable.</p>${locked?notice('This paper is locked. You can read your submission and feedback, but cannot change it.'):`<div class="actions"><button class="btn secondary" type="submit" value="save">Save draft</button>${r?.mcq==null?'<button class="btn secondary" type="submit" value="seal">Check Part A & seal</button>':''}<button class="btn" type="submit" value="submit">Hand in assignment</button></div>`}</form>`}${fileList(arr('files').filter(f=>f.course===c))}</div></div>`}
function exams(){const running=arr('exams').find(e=>e.status==='running');if(running){return heading('Server-timed sitting',esc(lev(running.level).name))+`<form id="examForm" data-id="${running.id}" data-level="${running.level}" data-version="${running.version}" data-deadline="${running.deadline}"><div class="timerbar row between"><div><b>Save regularly; the deadline does not pause.</b><br><span class="small" id="examSaveStatus">Saved answers are retained if time expires. Online changes auto-save after a short pause.</span></div><span id="examClock" class="exam-clock"></span></div><div class="card" style="margin-top:15px">${questionList(running.questions,running.answers)}<h2>Written answer</h2><p>In at least 250 words: ${esc(D.COURSES[lev(running.level).courses[0]].assignment)}</p><textarea name="essay" maxlength="30000">${esc(running.essay)}</textarea><div class="actions"><button type="submit" class="btn secondary" value="save">Save answers now</button><button type="submit" class="btn" value="submit">Hand in examination</button></div><p class="small">Closing this page does not cancel the sitting or restore the attempt. Reopen it to resume before the same server deadline.</p></div></form>`}
return heading('Assessment','Level examinations','Pass at least 60% of a level’s courses, then ask a school administrator to authorise a sitting. One failed-paper retake is permitted after 30 days and marking.')+`<div class="grid two">${S.mine.profile.levels.map(id=>{let l=lev(id),recs=arr('exams').filter(e=>e.level===id),passed=recs.some(e=>e.passed),permit=arr('permits').find(p=>p.level===id&&new Date(p.expires_at)>new Date(Date.now()+S.offset));return `<div class="card"><h2>${esc(l.name)}</h2><p class="small">40 objective questions · 60 minutes · written answer</p>${chip(passed?'Passed':permit?'Sitting authorised':'Ask the registrar',passed?'green':permit?'gold':'')}<div class="actions">${!passed?btn(recs.length?'Start authorised retake':'Start authorised examination','examstart:'+id,''):''}</div>${recs.map(e=>`<details><summary>Attempt ${e.attempt} · ${esc(e.status)}${e.mcq!=null?' · Objective '+e.mcq+'%':''}</summary><p>Submitted ${date(e.submitted_at)}</p><p>Written score: ${e.essay_score??'Awaiting marking'}</p><p class="preserve">${esc(e.feedback)}</p><h4>Your written answer</h4><p class="preserve">${esc(e.essay)}</p>${e.questions.map((q,i)=>`<p class="small">${i+1}. ${esc(q[0])}<br><b>Your answer:</b> ${esc(q[1][e.answers[i]]??'Not answered')}</p>`).join('')}</details>`).join('')}</div>`}).join('')}</div><div class="card"><h2>Departmental practice papers</h2><p class="small">Untimed revision only. Practice results do not count toward a level.</p><div class="actions">${D.EXAMS.map((e,i)=>btn(esc(e.title),'practice:'+i)).join('')}</div></div>${notice('The objective result is server-graded. The written answer must also receive at least 50% from the registrar before the exam can pass. No browser staff or invigilator code can unlock a sitting.')}`}
function fees(){if(S.cert)return certificateView(S.cert);return heading('Graduation','Fees & certificates','A payment claim is not a payment approval. Staff check the actual church Airtel Money account, then separately issue an academically eligible certificate.')+`<div class="grid two"><div class="card accent"><h2>K150 certificate fee</h2><p>Pay to <b>0979 554 970</b><br>Account name: <b>Emmanuel Sakala</b></p><p>Use <b>${esc(S.mine.profile.student_no)}</b> and your level as the payment reference.</p><p class="small">Do not send money to a number supplied in an unsolicited student message. Registration and study have no registration fee.</p></div><form id="paymentForm" class="card"><h3>Submit a payment claim</h3><label>Certificate level${selectLevels('level','',levels.filter(l=>S.mine.profile.levels.includes(l.id)))}</label>${input('Airtel Money transaction reference','reference','','text','required minlength="5" maxlength="100"')}${input('Sender phone number','phone',S.mine.profile.profile.phone,'tel','required maxlength="40"')}${input('Payment date','paid_on',new Date(Date.now()+7200000).toISOString().slice(0,10),'date','required')}<label class="check"><input type="checkbox" required><span>I paid K150 to the church line and entered the actual transaction reference. I understand this claim needs staff verification.</span></label><button type="submit" class="btn">Send claim to registrar</button><p class="small">After sending, use My files to attach the receipt to this claim.</p></form></div><h2>Payment decisions</h2>${paymentList(S.mine,false)}<h2 style="margin-top:26px">Certificate register</h2>${certificateList(S.mine,false)}${notice('Certificate release requires every course passed, a passed marked exam, a verified K150 payment, and a school administrator’s issue decision. A certificate may be revoked if eligibility is later corrected.')}`}
function paymentList(r,adminMode){return arr('payments',r).length?arr('payments',r).slice().reverse().map(p=>`<div class="card"><div class="row between"><h3>${esc(lev(p.level)?.name)} · K${p.amount}</h3>${chip(p.status,p.status==='verified'?'green':p.status==='rejected'?'red':'gold')}</div><p>${esc(p.transaction_ref)} · ${esc(p.sender_phone)} · ${esc(p.paid_on)}</p><p class="small preserve">${esc(p.note||'Awaiting manual verification against the church account.')}</p>${fileList(arr('files',r).filter(f=>f.payment_id===p.id))}${adminMode?`<div class="actions">${btn('Verify / reject claim','paymentreview:'+p.id)}</div>`:''}</div>`).join(''):'<div class="card"><p class="muted">No payment claims yet.</p></div>'}
function certificateList(r,adminMode){return r.profile.levels.map(id=>{const c=arr('certificates',r).find(c=>c.level===id);return `<div class="card"><div class="row between"><h3>${esc(lev(id).name)}</h3>${chip(c?(c.revoked?'Revoked':'Issued'):'Not issued',c&&!c.revoked?'green':c?.revoked?'red':'')}</div>${c?`<p>${esc(c.certificate_no)} · ${date(c.issued_at)}</p>${c.revoked?notice(esc(c.reason),'bad'):btn('View / download certificate','certificate:'+c.id)}`:'<p class="small">The registrar releases this after all requirements are met.</p>'}${adminMode?`<div class="actions">${btn(c?.revoked?'Recheck & reinstate certificate':'Check eligibility & issue','issue:'+id)}${c&&!c.revoked?btn('Revoke','revoke:'+c.id,'danger'):''}</div>`:''}</div>`}).join('')}
function certificateMarkup(c){return `<div class="certificate ${c.revoked?'revoked':''}"><img class="logo" src="${D.LOGO_SM}" alt="JCRGM logo"><p class="kicker">Jesus Christ Redeems Global Ministries</p><h2>Certificate of Completion</h2><p>This certifies that</p><div class="name">${esc(c.name)}</div><p>has fulfilled the recorded requirements for</p><h2 style="font-size:26px">${esc(c.level_name)}</h2><p>JCRGM Bible Institution · Lusaka, Zambia</p><div class="divider"></div><p><b>${esc(c.certificate_no)}</b><br>Issued ${date(c.issued_at)}</p><p class="small">Recorded by the school registrar. Verify this number with the school office: 0979 554 970.</p>${c.revoked?'<h2>REVOKED — NOT VALID</h2>':''}</div>`}
function certificateView(c){return heading('School register','Your certificate')+certificateMarkup(c)+`<div class="actions">${!c.revoked?btn('Download PDF','certpdf','')+btn('Print certificate','certprint'):''}${btn('Back','certback')}</div><p class="small">The server certificate record is authoritative. A downloaded PDF is not cryptographically signed and can’t be recalled after downloading.</p>`}
function fileList(list){const ready=list.filter(f=>f.ready);return ready.length?`<div>${ready.map(f=>`<div class="file-row row between"><span>${icon('file')} ${esc(f.name)} <span class="small">${(f.size/1024).toFixed(0)} KB</span></span>${btn('Open private file','file:'+f.id,'secondary smallbtn')}</div>`).join('')}</div>`:''}
function files(){let payments=arr('payments').filter(p=>p.status==='pending');return heading('Private supporting evidence','My files','PDF, JPG and PNG files up to 5 MB each. Files are visible only to you and appointed school staff. Upload documents before handing in coursework or payment review.')+`<form id="uploadForm" class="card"><div class="grid two"><div><label>Attach to<select name="context" required><optgroup label="Coursework">${S.mine.profile.levels.flatMap(id=>lev(id).courses).filter(c=>!['submitted','graded'].includes(assignment(c)?.status)).map(c=>`<option value="assignment:${c}">${esc(D.COURSES[c].title)}</option>`).join('')}</optgroup><optgroup label="Pending payment claims">${payments.map(p=>`<option value="receipt:${p.id}">${esc(p.transaction_ref)} · ${esc(p.level)}</option>`).join('')}</optgroup></select></label><label>Choose file<input type="file" name="file" accept="application/pdf,image/jpeg,image/png" required></label><button class="btn" type="submit">Upload private evidence</button><p class="small" id="uploadStatus">Evidence cannot be overwritten after upload. An incorrect file can be explained to the registrar through Messages.</p></div><div class="notice"><b>Protect personal information</b><p>Upload only the evidence needed for your school record. Redact unrelated bank balances, other people’s details and confidential ministry information.</p><p>Files are not automatically virus-scanned. Staff should open only expected, trusted evidence.</p></div></div></form><div class="card"><h2>Your uploaded files</h2>${fileList(arr('files'))||'<p class="muted">No completed uploads.</p>'}${arr('files').some(f=>!f.ready)?notice('Some reserved uploads did not finish. You can upload the file again; unfinished reservations are not shared as evidence.'):''}</div>`}
function records(){return heading('Academic record','Transcript & history',`${esc(S.mine.profile.profile.name)} · ${esc(S.mine.profile.student_no)}`)+`<div class="card" id="transcriptSheet">${transcript(S.mine)}<div class="actions">${btn('Download transcript CSV','transcriptcsv')}${btn('Print transcript','transcriptprint')}</div></div><div class="card"><h2>Bring an old offline record for review</h2><p>Your old record will be sent as <b>unverified evidence</b>. It will not automatically grant marks, payment approval, exam passes or certificates.</p><div class="actions">${btn('Submit old record from this browser','legacybrowser')}${btn('Download old browser backup','legacybackup')}</div><form id="legacyForm"><label>Or import an old JSON backup<input type="file" name="file" accept="application/json,.json" required></label><button class="btn secondary" type="submit">Submit JSON for staff review</button></form>${arr('legacy').length?notice('A legacy record has been submitted. Contact the registrar about credit decisions.','good'):''}</div>`}
function transcript(r){return `<p><b>${esc(r.profile.profile.name)}</b> · ${esc(r.profile.student_no)}</p><div class="table-wrap"><table><thead><tr><th>Course</th><th>Status</th><th>Objective</th><th>Essay</th><th>Final</th><th>Result</th></tr></thead><tbody>${r.profile.levels.flatMap(l=>lev(l).courses).map(c=>{let a=assignment(c,r);return `<tr><td>${esc(D.COURSES[c].title)}</td><td>${esc(a?.status||'Not submitted')}${a?.prior_learning?' · Prior learning':''}</td><td>${a?.mcq??'—'}</td><td>${a?.essay_score??'—'}</td><td>${a?.final_score??'—'}</td><td>${a?.passed?'Passed':'Not yet passed'}</td></tr>`}).join('')}</tbody></table></div>`}
function messages(){return heading('The registrar','Messages to the school office','Questions and replies are saved in your private school record. This page does not send SMS or WhatsApp notifications.')+messageThread(S.mine,false)}
function messageThread(r,adminMode){return `<div class="card"><form id="messageForm" data-student="${adminMode?r.profile.user_id:''}"><label>${adminMode?'Reply to this student':'Your enquiry'}<textarea name="body" maxlength="10000" required placeholder="Write clearly: what happened, what you need, and when."></textarea></label><button class="btn" type="submit">${adminMode?'Send staff reply':'Send to registrar'}</button></form><div class="divider"></div>${adminMode?btn('Mark student messages as read','messagesread'):''}${arr('messages',r).map(m=>`<article class="message ${m.from_staff?'staff':''}"><div class="row between"><b>${m.from_staff?'School administration':'Student'}</b><span class="small">${date(m.created_at)}</span></div><p class="preserve">${esc(m.body)}</p></article>`).join('')||'<p class="small">No messages yet.</p>'}<p class="small">Most recent 200 messages shown. For urgent enquiries: 0979 554 970.</p></div>`}
function library(){const block=(title,list)=>`<div class="card"><h2>${esc(title)}</h2>${list.map(b=>`<p><b>${esc(b[0])}</b><br><span class="small">${esc(b[1])} · ${esc(b[2])}</span></p>`).join('')}</div>`;return heading('Read deeply','The school library','Original reading lists retained. Confirm exact titles, authors and editions with the registrar before purchasing or citing them. Books are recommendations, not included full-text downloads.')+block('Core shelf',D.LIBRARY.core.concat(D.LIBRARY.shelf))+levels.map(l=>block(l.name,D.LIBRARY.byLevel[l.id]||[])).join('')+`<div class="card"><h2>Open study resources</h2><div class="actions">${[['BibleProject','https://bibleproject.com/'],['Yale Bible Study','https://oyc.yale.edu/religious-studies/rlst-145'],['Bible Gateway','https://www.biblegateway.com/resources/'],['Blue Letter Bible','https://www.blueletterbible.org/']].map(([t,u])=>`<a class="btn secondary" href="${u}" target="_blank" rel="noopener noreferrer">${t} ↗</a>`).join('')}</div><p class="small">These links open external websites only when you choose them. Judge teaching by Scripture and discuss questions with mature teachers.</p></div>`}
function handbook(){return heading('The covenant of study','Student handbook')+`<div class="card prose"><h2>Formation before a platform</h2><p>Study seriously, pray for wisdom, interpret Scripture in context and receive correction humbly. A course or level is intended for sustained study across a year; the platform does not prove time spent or prevent all cheating. The registrar oversees academic progression.</p><h3>Honest work and assessment</h3><p>Work through lessons in order. Complete each lesson check at 50% or above. Course assignments require all lessons completed, 20 objective answers, a typed essay within the stated word range, and a bibliography. Checking Part A seals your choices. The server computes objective results; staff mark essays against the published rubric.</p><p>A course passes when its weighted final mark reaches the level threshold and its objective mark is at least 50%. The registrar may return a paper once; resubmit within 30 days. Fabricated citations, plagiarism and dishonest ministry reports require staff review and may result in rejection or suspension.</p><h3>Supervised examinations</h3><p>Pass at least 60% of the courses in a level, then ask staff for a 24-hour permission to start the exam. A sitting uses a server deadline, normally 60 minutes for 40 questions. Closing the app does not restart time. Keep answers saved: after expiry, the server seals the last saved work. One retake is allowed after marking and 30 days if the first paper failed.</p><p>The objective pass is 60%, 65% for masters/prophetic, and 70% for doctoral levels. The written answer requires 250 words and a staff mark of at least 50%. The former browser invigilator code is not used.</p><h3>Fees and certificate release</h3><p>Registration is free. The certificate fee remains K150, paid to Airtel Money 0979 554 970, Emmanuel Sakala. Quote your student number and level. Submit the actual transaction reference and an optional receipt. Staff verify funds against the church account; uploaded evidence alone never automatically approves a payment.</p><p>Every course, the marked level exam and the payment must pass server eligibility checks. A school administrator then issues the certificate. Corrected marks, suspension or reversed payment verification may revoke it. Printed and downloaded copies cannot be recalled; check authenticity with the school’s register.</p><h3>Ministry accountability</h3><p>Prophetic and practical work is supervised. Provide dates, logs and supervisor confirmations. Do not include identifying private counselling details in assignments without a legitimate need and appropriate permission. No prophecy is ministered for money, fear or favour.</p><h3>Cloud records and privacy</h3><p>Your school account is separate from church membership approval. Once your email is confirmed and registration completed, study can begin immediately. Only you and appointed school staff can access your saved educational record. School administrators are appointed separately from church leaders.</p><p>Cloud saves need internet access. Use the Save buttons before leaving a page or changing devices. Password sign-in may remain on the device; sign out on shared devices. Private files use restricted storage and short-lived access links. Existing offline records can be submitted for review but do not automatically become trusted marks or approvals.</p><h3>Help and pastoral care</h3><p>Use Registrar messages for enquiries and corrections. For urgent issues call 0979 554 970 or email pedahzurministries@gmail.com. No automated WhatsApp, SMS, payment-provider integration or background push delivery is included.</p></div>`}
function calendar(){return heading('The rhythm of study','Academic calendar')+`<div class="card"><h2>2026–2027 school rhythm</h2><div class="table-wrap"><table><thead><tr><th>Term</th><th>Begins</th><th>Ends</th><th>Work</th></tr></thead><tbody>${D.TERMS.map(t=>'<tr>'+t.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')}</tbody></table></div><p>Term dates and current instructions are confirmed by the registrar through school notices. The dates in the former offline copy are not automatically extended or enforced as new deadlines.</p><div class="grid two">${[['Sunday','Word & prayer 08:00 · ministry 10:00 · class 12:30'],['Wednesday','Prayer chain 17:00 · tutorial 18:30'],['Friday','Prayer & deliverance 18:00 · practicum rehearsal 19:30'],['Saturday','Fieldwork 09:00 · assignment writing clinic 14:00']].map(([a,b])=>`<div><h3>${a}</h3><p>${b}</p></div>`).join('')}</div><p class="small">Zambia time · UTC+02:00. Confirm meeting arrangements with the school office.</p></div>`}
async function loadAdmin(){if(!staff())return;const epoch=S.epoch,target=S.selected,request=(S.adminRequest||0)+1;S.adminRequest=request;S.adminLoading=true;chrome();render();try{const students=await call('admin_students',{search:S.search,page:S.page});const view=target?await call('snapshot',{student:target}):null;if(epoch!==S.epoch||request!==S.adminRequest||target!==S.selected||!staff())return;S.students=students;S.view=view;S.adminLoading=false;chrome();render()}catch(e){if(epoch===S.epoch&&request===S.adminRequest){S.adminLoading=false;S.view=null;toast(e.message);await refresh(true)}}}
function admin(){if(!S.user)return gate();if(!staff())return heading('Restricted access','School administration')+notice('Only separately appointed school administrators can access student records. Church leadership and the old staff code do not grant access.','bad');return heading('Registrar workspace','School administration','Private registrations, marking, evidence, decisions and certificate records in one place.')+`<div class="adminnav">${['inbox','students','notices','audit',...(owner()?['staff']:[])].map(t=>btn(t[0].toUpperCase()+t.slice(1),'admintab:'+t,S.adminTab===t?'':'secondary')).join('')}</div>`+(S.adminLoading?'<div class="card">Loading the selected school record…</div>':S.adminTab==='inbox'?adminInbox():S.adminTab==='students'?(S.view?adminStudent():adminStudents()):S.adminTab==='staff'?adminStaff():S.adminTab==='notices'?adminNotices():adminAudit())}
function adminInbox(){return `<div class="card"><h2>Registrar inbox</h2><p class="small">Submitted coursework, payment claims, exams awaiting marking and unread student enquiries. Open a record to take action.</p><div id="inboxRows">Loading inbox…</div><div class="actions">${btn('Previous','inboxprev','secondary',!(S.inboxPage||0)?'disabled':'')}${chip('Page '+((S.inboxPage||0)+1))}${btn('Next','inboxnext')}</div></div>`}
function adminStudents(){const d=S.students||{};return `<div class="grid"><div class="card"><div class="value">${d.total||0}</div><h3>Registered students</h3></div><div class="card"><div class="value">${(d.pending_assignments||0)+(d.pending_exams||0)}</div><h3>Papers awaiting marking</h3></div><div class="card"><div class="value">${d.pending_payments||0}</div><h3>Payment claims</h3></div></div><div class="card" style="margin-top:20px"><form id="studentSearch" class="row"><input style="flex:1;min-width:180px" name="search" value="${esc(S.search)}" placeholder="Search name, email or student number"><button class="btn" type="submit">Search register</button></form><div class="table-wrap"><table><thead><tr><th>Student</th><th>Registration</th><th>Pending</th><th>Open</th></tr></thead><tbody>${(d.rows||[]).map(p=>`<tr><td><b>${esc(p.profile.name)}</b><br>${esc(p.email)}</td><td>${esc(p.student_no)}<br>${chip(p.active?'Active':'Suspended',p.active?'green':'red')}</td><td>${p.pending_assignments} assignments · ${p.pending_exams} exams<br>${p.pending_payments} payments</td><td>${btn('Review record','student:'+p.user_id,'secondary smallbtn')}</td></tr>`).join('')}</tbody></table></div><div class="actions">${btn('Previous','adminprev','secondary',S.page===0?'disabled':'')}${chip('Page '+(S.page+1))}${btn('Next','adminnext','secondary',(d.rows||[]).length<50?'disabled':'')}${btn('Export this page CSV','registercsv')}${btn('Payment ledger CSV','paymentcsv')}</div><p class="small">50 students per page. No student data is shown to unauthorised church leaders.</p></div>`}
function adminStudent(){const r=S.view,p=r.profile;if(!p)return notice('This student was not found.');return `<div class="actions" style="margin-bottom:18px">${btn('← Student register','studentback')}${btn('Messages','studenttab:messages')}${btn('Transcript','studenttab:transcript')}${btn('Work & decisions','studenttab:work')}</div><div class="card"><div class="row between"><div><h2>${esc(p.profile.name)}</h2><p>${esc(p.student_no)} · ${esc(p.email)}</p></div>${chip(p.active?'Active':'Suspended',p.active?'green':'red')}</div><details><summary>Registration details & access</summary><div class="grid two">${Object.entries(p.profile).filter(([k])=>k!=='covenant').map(([k,v])=>`<div><b>${esc(k.replaceAll('_',' '))}</b><p class="small preserve">${esc(v)}</p></div>`).join('')}</div><form id="studentAccess" data-version="${p.version}">${input('Certificate name','name',p.profile.name,'text','required maxlength="120"')}<label class="check"><input type="checkbox" name="active" ${p.active?'checked':''}> Active student access</label><button class="btn secondary" type="submit">Save name / access decision</button></form></details></div>${S.studentTab==='messages'?messageThread(r,true):S.studentTab==='transcript'?`<div class="card">${transcript(r)}${btn('Download transcript CSV','admintranscriptcsv')}</div>`:adminWork(r)}`}
function adminWork(r){return `<h2>Assignments & marking</h2>${arr('assignments',r).map(a=>`<div class="card"><div class="row between"><h3>${esc(D.COURSES[a.course].title)}</h3>${chip(a.status,a.passed?'green':'')}</div><p>Objective: ${a.mcq??'Not sealed'}% · Final: ${a.final_score??'Not marked'}</p><details><summary>Read submission, answers and supporting files</summary><h4>Essay</h4><p class="preserve">${esc(a.essay)}</p><h4>Bibliography</h4><p class="preserve">${esc(a.bibliography)}</p>${(D.BANK[a.course]||[]).map((q,i)=>`<p class="small">${i+1}. ${esc(q[0])}<br><b>Student:</b> ${esc(q[1][a.answers[i]]??'Not answered')}</p>`).join('')}${fileList(arr('files',r).filter(f=>f.course===a.course))}</details>${a.feedback?`<p class="small preserve">${esc(a.feedback)}</p>`:''}<div class="actions">${a.status==='submitted'?btn('Mark using rubric','grade:'+a.course,''):''}${['submitted','graded'].includes(a.status)&&a.attempts<2?btn('Return for one correction','return:'+a.course):''}</div></div>`).join('')||'<div class="card">No saved assignments yet.</div>'}<h2>Examination decisions</h2><div class="card"><div class="actions">${r.profile.levels.map(l=>btn('Authorise '+lev(l).name+' · 24h','permit:'+l)).join('')}</div>${arr('exams',r).map(e=>`<details><summary>${esc(lev(e.level).name)} · Attempt ${e.attempt} · ${esc(e.status)} · ${e.mcq??'—'}%</summary><p class="preserve">${esc(e.essay)}</p><p>Deadline: ${date(e.deadline)}</p><p class="small preserve">${esc(e.feedback)}</p>${e.status==='submitted'?btn('Mark written answer','examgrade:'+e.id,''):''}</details>`).join('')}</div><h2>Payment verification</h2>${paymentList(r,true)}<h2>Certificates</h2>${certificateList(r,true)}<h2>Private supporting documents</h2><div class="card">${fileList(arr('files',r))||'No completed uploads.'}</div>${arr('legacy',r).length?`<div class="card"><h2>Imported record — unverified</h2><p>Compare old marks and claims with original school evidence. Importing did not approve anything.</p>${btn('Download submitted legacy record','legacydownload')}<div class="actions">${r.profile.levels.flatMap(l=>lev(l).courses).filter(c=>!['submitted','graded'].includes(assignment(c,r)?.status)).map(c=>btn('Record reviewed credit: '+c,'credit:'+c)).join('')}</div></div>`:''}`}
function adminStaff(){return `<div class="card"><h2>Appoint or revoke school staff</h2><p>The person must first create and confirm an account. Only school owners can appoint staff. At least one active owner must remain.</p><form id="staffForm">${input('Confirmed account email','email','','email','required')}<label>Role<select name="role"><option value="admin">School administrator</option><option value="owner">School owner — can appoint staff</option></select></label><label class="check"><input name="active" type="checkbox" checked> Active staff access</label><button type="submit" class="btn">Apply staff decision</button></form><div id="staffRows" style="margin-top:22px">Loading staff…</div></div>`}
function adminNotices(){return `<div class="card"><h2>School notices</h2><p>These notices appear to registered students. Use them for term dates and school instructions; the church’s public Announcements board is separate.</p><form id="noticeForm">${input('Title','title','','text','required maxlength="180"')}<label>Message<textarea name="body" required maxlength="12000"></textarea></label><label class="check"><input type="checkbox" name="published" checked> Publish to registered students</label><button type="submit" class="btn">Publish school notice</button></form><div id="noticeRows" style="margin-top:25px">Loading notices…</div></div>`}
function adminAudit(){return `<div class="card"><h2>Administrative audit</h2><p class="small">Most recent 200 administrative and student events. The complete log remains in the database.</p><div id="auditRows">Loading audit…</div></div>`}
function formData(form){return Object.fromEntries(new FormData(form).entries())}
function collectAnswers(form,n,prefix='q'){return Array.from({length:n},(_,i)=>{const x=form.querySelector(`input[name="${prefix+i}"]:checked`);return x?Number(x.value):null})}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>go(b.dataset.route));$('main').querySelectorAll('form:not(#studentSearch)').forEach(f=>f.addEventListener('input',()=>{S.dirty=true;status();if(f.id==='examForm'){clearTimeout(S.examDebounce);S.examDebounce=setTimeout(()=>saveExam('save',true),1800)}}));
const handlers={enrolForm:e=>work(()=>call('enrol',{level:e.target.elements.level.value,version:S.mine.profile.version}),'Study level added.'),registration:registerSubmit,learningForm:learningSubmit,assignmentForm:assignmentSubmit,paymentForm:paymentSubmit,uploadForm:uploadSubmit,messageForm:messageSubmit,legacyForm:legacySubmit,studentAccess:studentAccessSubmit,staffForm:staffSubmit,noticeForm:noticeSubmit,examForm:e=>saveExam(e.submitter?.value||'save'),studentSearch:async e=>{S.search=new FormData(e.target).get('search').trim();S.page=0;await loadAdmin()}};for(const [id,fn]of Object.entries(handlers))if($(id))$(id).onsubmit=e=>{e.preventDefault();Promise.resolve(fn(e)).catch(err=>toast(err.message))};if($('assignmentForm'))$('assignmentForm').querySelector('[name=essay]').addEventListener('input',e=>$('wordCount').textContent=wordCount(e.target.value)+' words');if(S.route==='admin'&&staff())loadAdminExtras()}
async function registerSubmit(e){let f=formData(e.target),chosen=new FormData(e.target).getAll('levels');f.covenant=true;delete f.levels;await work(()=>call('register',{profile:f,levels:chosen}),'You are registered. Your study access is active.');if(S.mine?.profile)await go('dashboard')}
async function learningSubmit(e){const f=e.target,l=D.COURSES[S.course].lessons[S.lesson];await work(()=>call('save_learning',{course:S.course,lesson:S.lesson,notes:f.elements.notes.value,answers:collectAnswers(f,l.quiz.length),finish:e.submitter?.value==='finish',version:Number(f.dataset.version)}),'Lesson record saved.')}
async function assignmentSubmit(e){const f=e.target,op=e.submitter?.value||'save';if(op==='seal'&&!confirm('Check and seal Part A? The choices cannot be edited unless the registrar returns the paper.'))return;if(op==='submit'&&!confirm('Hand in this assignment? Its text and choices will be locked for marking.'))return;await work(()=>call('assignment',{course:S.course,operation:op,data:{answers:collectAnswers(f,D.BANK[S.course].length),essay:f.elements.essay.value,bibliography:f.elements.bibliography.value},version:Number(f.dataset.version),catalog:D.VERSION}),op==='submit'?'Assignment handed in to the registrar.':op==='seal'?'Objective answers sealed and scored.':'Draft saved online.')}
async function paymentSubmit(e){const d=formData(e.target);await work(()=>call('claim_payment',{level:d.level,reference:d.reference,phone:d.phone,paid_on:d.paid_on}),'Claim sent. Attach its receipt under My files. This is not yet a payment approval.')}
async function uploadSubmit(e){const f=e.target,file=f.elements.file.files[0];if(!file)return;const [kind,context]=f.elements.context.value.split(':');if(!['application/pdf','image/jpeg','image/png'].includes(file.type)||file.size>5242880||file.size<1)throw Error('Choose a PDF, JPG or PNG no larger than 5 MB.');await work(async()=>{const r=await call('file',{operation:'reserve',data:{kind,course:kind==='assignment'?context:null,payment_id:kind==='receipt'?context:null,name:file.name,size:file.size,mime:file.type}});$('uploadStatus').textContent='Uploading securely… keep this page open.';const {error}=await S.client.storage.from('jcrgm-school-private').upload(r.path,file,{contentType:file.type,upsert:false,cacheControl:'0'});if(error)throw error;await call('file',{operation:'finish',id:r.id});},'Private evidence uploaded.')}
async function messageSubmit(e){const body=e.target.elements.body.value;await work(()=>call('message',{student:e.target.dataset.student||null,body}),'Message saved for the registrar/student. No SMS notification was sent.')}
async function legacySubmit(e){let file=e.target.elements.file.files[0];if(file.size>2500000)throw Error('Import a JSON file up to 2.5 MB.');let d=JSON.parse(await file.text());if(!confirm('Submit this old record for staff review? It will not automatically grant marks or approvals.'))return;await work(()=>call('import_legacy',{data:d}),'Old record submitted as unverified evidence.')}
async function studentAccessSubmit(e){let f=e.target;await work(()=>adminCall('student',{data:{name:f.elements.name.value,active:f.elements.active.checked},version:Number(f.dataset.version)}),'Student name / access updated.')}
async function staffSubmit(e){let f=e.target;if(!confirm('Apply this school staff access decision? Administrators can access all student records.'))return;await work(()=>adminCall('staff',{student:null,data:{email:f.elements.email.value,role:f.elements.role.value,active:f.elements.active.checked}}),'School staff decision recorded.')}
async function noticeSubmit(e){let f=e.target;await work(()=>adminCall('notice',{student:null,data:{title:f.elements.title.value,body:f.elements.body.value,published:f.elements.published.checked}}),'School notice saved.')}
const adminCall=(action,more={})=>call('admin',{action,student:S.selected,...more});
function modal(title,html){$('modal').innerHTML=`<button class="close" type="button" id="closeModal" aria-label="Close">×</button><h2>${title}</h2>${html}`;$('closeModal').onclick=()=>{$('modal').close();$('modal').replaceChildren()};if(!$('modal').open)$('modal').showModal()}
function modalForm(title,html,submit){modal(title,`<form id="decisionForm">${html}<p class="form-status" id="decisionStatus"></p><button type="submit" class="btn">Save decision</button></form>`);$('decisionForm').onsubmit=async e=>{e.preventDefault();const f=e.target;f.querySelector('button[type=submit]').disabled=true;const epoch=S.epoch;try{await submit(f);if(epoch!==S.epoch)return;$('modal').close();$('modal').replaceChildren();S.dirty=false;await refresh(true);toast('Administrative decision saved.')}catch(err){if($('decisionStatus'))$('decisionStatus').textContent=err.message}finally{const b=f.querySelector('button[type=submit]');if(b)b.disabled=false}}}
function markDialog(code,credit=false){const a=assignment(code,S.view),sp=spec(code);modalForm(credit?'Record reviewed prior learning':'Mark '+esc(code),`<p class="small">${credit?'Only record marks verified against original evidence. Imported local values are not trusted.':'Objective score: '+a.mcq+'%. Mark the essay using each criterion below.'}</p>${credit?input('Verified objective percentage','mcq','','number','min="0" max="100" required'):''}${sp.rubric.map((r,i)=>`<div class="rubric"><label for="rub${i}"><b>${esc(r[0])}</b><br><span class="small">${esc(r[2])} · maximum ${r[1]}</span></label><input id="rub${i}" name="rub${i}" type="number" min="0" max="${r[1]}" required></div>`).join('')}<label>Feedback / verification reason<textarea name="feedback" maxlength="12000" ${credit?'minlength="20"':''} required></textarea></label>`,f=>adminCall(credit?'prior_learning':'grade',{code,version:a?.version||0,data:{marks:sp.rubric.map((_,i)=>Number(f.elements['rub'+i].value)),feedback:f.elements.feedback.value,...(credit?{mcq:Number(f.elements.mcq.value)}:{})}}))}
async function action(text){const [a,...rest]=text.split(':'),v=rest.join(':');try{if(S.dirty&&!['file','legacybackup','transcriptcsv','admintranscriptcsv','registercsv','paymentcsv','signout'].includes(a)){if(!confirm('This action may replace the current form. Save or copy your unsaved text first. Continue without it?'))return;S.dirty=false}if(a==='route')return go(v);if(a==='signin')return auth('login');if(a==='signout')return signOut();if(a==='course'||a==='assignment'){if(S.dirty&&!confirm('Discard unsaved work and change course?'))return;S.dirty=false;S.course=v;S.lesson=0;return go(a==='course'?'lessons':'assignments')}if(a==='lesson'){if(S.dirty&&!confirm('Discard unsaved notes and change lesson?'))return;S.dirty=false;S.lesson=Number(v);return render()}if(a==='practice'){const paper=D.EXAMS[Number(v)];modal(esc(paper.title),`<form id="practiceForm">${questionList(paper.qs)}<button class="btn" type="submit">Check practice answers</button><p id="practiceScore" role="status"></p></form>`);$('practiceForm').onsubmit=e=>{e.preventDefault();const answers=collectAnswers(e.target,paper.qs.length);$('practiceScore').textContent=paper.qs.filter((q,i)=>q[2]===answers[i]).length+' / '+paper.qs.length+' correct. This is practice, not a recorded grade.'};return}if(a==='examstart'){if(!confirm('Start the server-timed exam now? Closing the app will not cancel the attempt.'))return;return work(()=>call('exam',{level:v,operation:'start'}),'Examination started. Save answers regularly.')}if(a==='file')return openFile(v);if(a==='certificate'){const r=S.route==='admin'?S.view:S.mine;S.cert=arr('certificates',r).find(c=>c.id===v);if(S.route==='admin'){S.route='fees';S.certAdmin=true}else S.certAdmin=false;$('main').innerHTML=certificateView(S.cert);bind();return}if(a==='certback'){S.cert=null;S.route=S.certAdmin?'admin':'fees';return render()}if(a==='certpdf'||a==='certprint')return outputCertificate(a==='certpdf');if(a==='transcriptcsv'||a==='admintranscriptcsv')return exportTranscript(a==='admintranscriptcsv'?S.view:S.mine);if(a==='transcriptprint'){await refresh(true);if(!active())throw Error('An active registration is required.');document.body.classList.add('print-transcript');window.print();return}if(a==='legacybackup'||a==='legacybrowser'){let data={student:JSON.parse(localStorage.getItem('jcrgm_student')||'null'),state:JSON.parse(localStorage.getItem('jcrgm_state')||'null'),fees:JSON.parse(localStorage.getItem('jcrgm_fees')||'null'),drafts:JSON.parse(localStorage.getItem('jcrgm_drafts')||'null')};if(!data.student&&!data.state)throw Error('No old record was found in this browser and website origin. Import a JSON backup from the original device.');if(a==='legacybackup')return download('JCRGM-private-old-school-record.json',JSON.stringify(data,null,2),'application/json');if(!confirm('Submit this old browser record for review? Its marks and payments will remain unverified.'))return;return work(()=>call('import_legacy',{data}),'Old record submitted for review.')}
if(!staff())throw Error('School administrator access is required.');if(a==='admintab'){if(S.dirty&&!confirm('Discard unsaved work?'))return;S.dirty=false;S.adminTab=v;S.selected=null;S.view=null;return loadAdmin()}if(a==='inbox'){const [id,kind]=v.split(':');S.selected=id;S.adminTab='students';S.studentTab=kind==='message'?'messages':'work';return loadAdmin()}if(a==='inboxprev'||a==='inboxnext'){S.inboxPage=Math.max(0,(S.inboxPage||0)+(a==='inboxnext'?1:-1));return render()}if(a==='messagesread')return work(()=>adminCall('messages_read'),'Student messages marked as read.');if(a==='student'){S.adminTab='students';S.selected=v;S.studentTab='work';return loadAdmin()}if(a==='studentback'){S.selected=null;S.view=null;return loadAdmin()}if(a==='studenttab'){S.studentTab=v;return render()}if(a==='adminprev'||a==='adminnext'){S.page=Math.max(0,S.page+(a==='adminnext'?1:-1));return loadAdmin()}if(a==='registercsv')return exportRegister();if(a==='paymentcsv')return exportPayments();if(a==='grade'||a==='credit')return markDialog(v,a==='credit');if(a==='return'){let r=assignment(v,S.view);return modalForm('Return assignment',`<p>One resubmission within 30 days is allowed. This clears the objective seal and any previous pass.</p><label>Required correction<textarea name="feedback" required minlength="3"></textarea></label>`,f=>adminCall('return',{code:v,version:r.version,data:{feedback:f.elements.feedback.value}}))}if(a==='paymentreview'){let p=arr('payments',S.view).find(p=>p.id===v);return modalForm('Review payment claim',`<p><b>K150</b> · ${esc(p.transaction_ref)}<br>${esc(p.sender_phone)} · ${esc(p.paid_on)}</p><label>Decision<select name="status"><option value="verified">Verify received payment</option><option value="rejected">Reject / reverse verification</option></select></label><label class="check"><input name="confirmed" type="checkbox"> I checked the actual church Airtel Money account, not only a receipt.</label><label>Audit note / explanation<textarea name="note" required minlength="3" maxlength="4000"></textarea></label>`,f=>adminCall('payment',{id:v,version:p.version,data:{status:f.elements.status.value,note:f.elements.note.value,confirmed_received:f.elements.confirmed.checked}}))}if(a==='permit'){if(confirm('Authorise this student to start '+lev(v).name+' within the next 24 hours?'))return work(()=>adminCall('exam_permit',{code:v}),'One exam sitting authorised for 24 hours.');return}if(a==='examgrade'){let ex=arr('exams',S.view).find(e=>e.id===v);return modalForm('Mark examination writing',`<p>Objective: ${ex.mcq}% · Written answer: ${wordCount(ex.essay)} words. A written mark of at least 50% and 250 words is required.</p>${input('Written-answer score / 100','score','','number','min="0" max="100" required')}<label>Feedback<textarea name="feedback" required minlength="3"></textarea></label>`,f=>adminCall('exam_grade',{id:v,version:ex.version,data:{score:Number(f.elements.score.value),feedback:f.elements.feedback.value}}))}if(a==='issue'){if(confirm('Check all server requirements and issue or reinstate this level’s certificate?'))return work(()=>adminCall('certificate_issue',{code:v}),'Certificate eligibility checked and issue recorded.');return}if(a==='revoke')return modalForm('Revoke certificate','<label>Reason<textarea name="reason" required minlength="5"></textarea></label>',f=>adminCall('certificate_revoke',{id:v,data:{reason:f.elements.reason.value}}));if(a==='legacydownload'){let {data,error}=await S.client.from('school_legacy').select('data').eq('student_id',S.selected).single();if(error)throw error;return download('UNVERIFIED-private-legacy-record.json',JSON.stringify(data.data,null,2),'application/json')}if(a==='noticehide'){let n=S.adminNotices.find(n=>n.id===v);return work(()=>adminCall('notice',{student:null,id:v,version:n.version,data:{title:n.title,body:n.body,published:!n.published}}),'Notice publication updated.')}}catch(e){toast(e.message)}}
async function loadAdminExtras(){const epoch=S.epoch;try{if(S.adminTab==='inbox'){const data=await call('admin_inbox',{page:S.inboxPage||0});if(epoch===S.epoch&&$('inboxRows')){$('inboxRows').innerHTML=data.map(x=>`<div class="file-row row between"><div><b>${esc(x.student_name)}</b> · ${chip(x.kind)}<p class="small">${esc(x.detail)}<br>${esc(x.student_no)} · ${date(x.created_at)}</p></div>${btn('Review','inbox:'+x.student_id+':'+x.kind)}</div>`).join('')||'<p class="muted">No pending items on this page.</p>';$('inboxRows').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action))}}if(S.adminTab==='staff'&&owner()){let {data,error}=await S.client.from('school_staff').select('*').order('email');if(error)throw error;if(epoch===S.epoch&&$('staffRows'))$('staffRows').innerHTML=(data||[]).map(x=>`<p>${esc(x.email)} · ${esc(x.role)} · ${x.active?'Active':'Revoked'}</p>`).join('')}if(S.adminTab==='notices'){let {data,error}=await S.client.from('school_notices').select('*').order('updated_at',{ascending:false}).limit(200);if(error)throw error;if(epoch===S.epoch&&$('noticeRows')){S.adminNotices=data;$('noticeRows').innerHTML=data.map(n=>`<div class="card"><h3>${esc(n.title)}</h3><p class="preserve">${esc(n.body)}</p>${chip(n.published?'Published':'Draft')}${btn(n.published?'Unpublish':'Publish','noticehide:'+n.id)}</div>`).join('');$('noticeRows').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action))}}if(S.adminTab==='audit'){let {data,error}=await S.client.from('school_audit').select('*').order('created_at',{ascending:false}).limit(200);if(error)throw error;if(epoch===S.epoch&&$('auditRows'))$('auditRows').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Actor</th><th>Details</th></tr></thead><tbody>${data.map(r=>`<tr><td>${date(r.created_at)}</td><td>${esc(r.action)}</td><td>${esc(r.actor)}</td><td><details><summary>Audit detail</summary><pre class="preserve">${esc(JSON.stringify(r.detail,null,2))}</pre></details></td></tr>`).join('')}</tbody></table></div>`}}catch(e){toast(e.message)}}
async function openFile(id){const r=S.route==='admin'?S.view:S.mine,f=arr('files',r).find(f=>f.id===id&&f.ready);if(!f)throw Error('File not found. Refresh the record.');const popup=window.open('about:blank','_blank');try{const {data,error}=await S.client.storage.from('jcrgm-school-private').createSignedUrl(f.path,60);if(error)throw error;if(popup){popup.opener=null;popup.location=data.signedUrl}else{modal('Private file link',`<p>This authorised link expires in 60 seconds. Do not share it.</p><a class="btn" href="${esc(data.signedUrl)}" target="_blank" rel="noopener noreferrer">Open ${esc(f.name)}</a>`)}}catch(e){popup?.close();throw e}}
async function saveExam(op,quiet=false){const f=$('examForm');if(!f||S.busy)return;if(op==='submit'&&!quiet&&!confirm('Hand in the examination? It cannot be edited afterwards.'))return;if(S.examSaving){if(op==='submit')S.queuedExamSubmit=true;return}S.examSaving=true;const epoch=S.epoch,values={answers:collectAnswers(f,arr('exams').find(e=>e.id===f.dataset.id).questions.length),essay:f.elements.essay.value},signature=JSON.stringify(values);try{const r=await call('exam',{level:f.dataset.level,operation:op,id:f.dataset.id,...values,version:Number(f.dataset.version)});if(epoch!==S.epoch)return;S.mine.exams=S.mine.exams.map(e=>e.id===r.id?r:e);if($('examForm')!==f)return;if(r.status!=='running'){S.dirty=false;toast('Examination sealed. Its written answer is awaiting marking.');await refresh(true);render()}else{f.dataset.version=r.version;const current=JSON.stringify({answers:collectAnswers(f,r.questions.length),essay:f.elements.essay.value});if(current===signature)S.dirty=false;if($('examSaveStatus'))$('examSaveStatus').textContent='Saved online at '+date(new Date());status();}}catch(e){if($('examSaveStatus'))$('examSaveStatus').textContent=e.message;if(!quiet)toast(e.message)}finally{S.examSaving=false;if(S.queuedExamSubmit){S.queuedExamSubmit=false;setTimeout(()=>saveExam('submit',true),0)}}}
function updateClock(){const f=$('examForm');if(!f||!$('examClock'))return;let left=Math.max(0,Math.ceil((new Date(f.dataset.deadline).getTime()-(Date.now()+S.offset))/1000));$('examClock').textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');if(left===0&&!S.examSaving&&navigator.onLine&&Date.now()>(S.nextExpiryTry||0)){S.nextExpiryTry=Date.now()+10000;saveExam('submit',true)}}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
const csvCell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r\n]|^\s+[=+@\-]/,"'$&").replaceAll('"','""')+'"';
function exportTranscript(r){let lines=[['Student',r.profile.profile.name,'ID',r.profile.student_no],['Course','Status','MCQ','Essay','Final','Passed','Feedback'],...r.profile.levels.flatMap(l=>lev(l).courses).map(c=>{let a=assignment(c,r);return [c,a?.status||'',a?.mcq??'',a?.essay_score??'',a?.final_score??'',a?.passed?'Yes':'No',a?.feedback||'']})];download(r.profile.student_no+'-private-transcript.csv','\ufeff'+lines.map(l=>l.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function exportRegister(){let lines=[['Student number','Name','Email','Phone','Levels','Active'],...(S.students?.rows||[]).map(p=>[p.student_no,p.profile.name,p.email,p.profile.phone,p.levels.join('; '),p.active])];download('private-school-register-page-'+(S.page+1)+'.csv','\ufeff'+lines.map(l=>l.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
async function exportPayments(){const epoch=S.epoch;let all=[];for(let offset=0;;offset+=500){const {data,error}=await S.client.from('school_payments').select('*').order('created_at').order('id').range(offset,offset+499);if(error)throw error;if(epoch!==S.epoch||!staff())throw Error('Staff access changed; export cancelled.');all.push(...data);if(data.length<500)break;}let lines=[['Claim ID','Student account ID','Level','Amount ZMW','Transaction','Sender phone','Paid on','Status','Note','Reviewed at','Reviewed by'],...all.map(p=>[p.id,p.student_id,p.level,p.amount,p.transaction_ref,p.sender_phone,p.paid_on,p.status,p.note,p.reviewed_at,p.reviewed_by])];download('private-school-payment-ledger.csv','\ufeff'+lines.map(l=>l.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
async function outputCertificate(pdf){const old=S.cert,uid=S.certAdmin?S.selected:null,epoch=S.epoch;const fresh=await call('snapshot',{student:uid});if(epoch!==S.epoch)return;const c=arr('certificates',fresh).find(c=>c.id===old.id&&!c.revoked);if(!c)throw Error('This certificate is no longer available or has been revoked.');if(!pdf){$('main').innerHTML=heading('Certificate register','Certificate of completion')+certificateMarkup(c);setTimeout(()=>window.print(),150);return}if(!window.jspdf)throw Error('The PDF library is missing. Keep vendor/jspdf.school.min.js beside the school files.');const doc=new window.jspdf.jsPDF({orientation:'landscape',unit:'mm',format:'a4'});doc.setFillColor(255,253,246);doc.rect(0,0,297,210,'F');doc.setDrawColor(174,137,57);doc.setLineWidth(1.2);doc.rect(10,10,277,190);doc.setLineWidth(.3);doc.rect(13,13,271,184);doc.addImage(D.LOGO_SM,'PNG',136,20,25,25);doc.setTextColor(28,47,73);doc.setFont('times','normal');doc.setFontSize(12);doc.text('JESUS CHRIST REDEEMS GLOBAL MINISTRIES',148.5,54,{align:'center'});doc.setFontSize(30);doc.text('Certificate of Completion',148.5,74,{align:'center'});doc.setFontSize(12);doc.text('This certifies that',148.5,91,{align:'center'});doc.setFontSize(25);doc.text(doc.splitTextToSize(c.name,245),148.5,108,{align:'center'});doc.setFontSize(12);doc.text('has fulfilled the recorded requirements for',148.5,129,{align:'center'});doc.setFontSize(19);doc.text(doc.splitTextToSize(c.level_name,245),148.5,142,{align:'center'});doc.setFontSize(11);doc.text('JCRGM Bible Institution | Lusaka, Zambia',148.5,162,{align:'center'});doc.text(c.certificate_no+' | Issued '+new Date(c.issued_at).toLocaleDateString('en-GB',{timeZone:'Africa/Lusaka'}),148.5,174,{align:'center'});doc.setFontSize(9);doc.text('Recorded in the school register. Verify with the registrar: 0979 554 970.',148.5,187,{align:'center'});doc.save(c.certificate_no+'.pdf')}
function auth(mode='login'){const signup=mode==='signup',reset=mode==='reset',recover=mode==='recover';modal(recover?'Set a new password':reset?'Reset your password':signup?'Create your school sign-in':'Welcome back',`<p class="small">${signup?'Confirm your email, then complete school registration to start immediately. Existing church-app accounts can sign in here without creating another account.':'Use your school or existing church-app email and password. School staff roles are assigned separately.'}</p><form id="authForm">${signup?input('Your name','name','','text','required maxlength="120"'):''}${!recover?input('Email','email','','email','required autocomplete="email"'):''}${!reset?input('Password','password','','password',`required ${signup||recover?'minlength="10"':''} autocomplete="${signup||recover?'new-password':'current-password'}"`):''}<p id="authStatus" class="form-status" role="status"></p><button class="btn" type="submit">${recover?'Update password':reset?'Send reset link':signup?'Create account':'Sign in'}</button></form>${!recover?`<div class="actions">${btn(signup?'Already registered? Sign in':'New student? Create account','switchAuth')}${btn('Forgot password?','resetAuth')}</div>`:''}`);$('modal').querySelector('[data-action=switchAuth]')?.addEventListener('click',()=>auth(signup?'login':'signup'));$('modal').querySelector('[data-action=resetAuth]')?.addEventListener('click',()=>auth('reset'));$('authForm').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button'),out=$('authStatus'),d=formData(f),redirect=new URL('JCRGM_Bible_Institution.html',location.href).href.split('#')[0];b.disabled=true;out.textContent='Please wait…';try{let res;if(signup)res=await S.client.auth.signUp({email:d.email,password:d.password,options:{data:{display_name:d.name},emailRedirectTo:redirect}});else if(reset)res=await S.client.auth.resetPasswordForEmail(d.email,{redirectTo:redirect});else if(recover)res=await S.client.auth.updateUser({password:d.password});else res=await S.client.auth.signInWithPassword({email:d.email,password:d.password});if(res.error)throw res.error;if(signup||reset){out.textContent=signup?'Check your email and confirm your account. Then return here and sign in.':'If the account exists, check its email for a reset link.';if(f.elements.password)f.elements.password.value=''}else{$('modal').close();$('modal').replaceChildren();await refresh(true)}}catch(err){out.textContent=err.message}finally{b.disabled=false}}}
async function signOut(){if(!confirm('Sign out on this device? Any unsaved text will be discarded.'))return;const {error}=await S.client.auth.signOut({scope:'local'});clearPrivate();S.user=null;S.route='home';render();if(error){try{localStorage.removeItem(S.storageKey);localStorage.removeItem(S.storageKey+'-code-verifier')}catch(e){}location.replace(new URL('JCRGM_Bible_Institution.html',location.href).href)}}
async function boot(){try{const cfg=window.JCRGM_SUPABASE;if(!cfg?.url||!cfg.key||cfg.key.includes('YOUR_')||cfg.key.startsWith('sb_secret_'))throw Error('Public Supabase configuration is missing or invalid.');if(!window.supabase)throw Error('Keep vendor/supabase.js in the upload.');S.storageKey='jcrgm-shared-'+new URL(cfg.url).hostname.split('.')[0]+'-auth';S.client=supabase.createClient(cfg.url,cfg.key,{auth:{storageKey:S.storageKey,persistSession:true,autoRefreshToken:true,detectSessionInUrl:true},global:{fetch:(url,options)=>fetch(url,{...options,cache:'no-store'})}});S.client.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'||(S.user&&session?.user?.id&&session.user.id!==S.user.id)){clearPrivate();S.user=null;S.route='home';render()}setTimeout(async()=>{await refresh();if(event==='PASSWORD_RECOVERY')auth('recover')},0)});await refresh();let initial=location.hash.slice(1);if(['register','dashboard','curriculum','lessons','assignments','exams','fees','files','records','messages','library','handbook','calendar','admin'].includes(initial)){S.route=initial;render()}setInterval(()=>{if(!S.busy&&!S.examSaving)refresh()},20000);setInterval(updateClock,1000);setInterval(()=>{if($('examForm')&&S.dirty&&navigator.onLine)saveExam('save',true)},10000);if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('service-worker.js',{updateViaCache:'none'}).catch(()=>{});}catch(e){S.ready=true;S.error=e.message;chrome();render();toast(e.message)}}
$('brandLogo').src=D.LOGO_SM;try{document.documentElement.dataset.theme=localStorage.getItem('jcrgm-school-theme')||'navy'}catch(e){}$('theme').value=document.documentElement.dataset.theme;$('theme').onchange=e=>{document.documentElement.dataset.theme=e.target.value;try{localStorage.setItem('jcrgm-school-theme',e.target.value)}catch(e){}};
window.addEventListener('afterprint',()=>document.body.classList.remove('print-transcript'));window.addEventListener('beforeunload',e=>{if(S.dirty){e.preventDefault();e.returnValue=''}});window.addEventListener('offline',()=>{S.online=false;S.error='Offline — keep this tab open. Reconnect before saving.';status()});window.addEventListener('online',()=>refresh());window.addEventListener('unhandledrejection',e=>{toast(e.reason?.message||'The operation failed.');e.preventDefault()});boot();
})();
